  existsSync: jest.fn().mockReturnValue(true),
  mkdirSync: jest.fn(),
  readFileSync: jest.fn().mockReturnValue(''),
}));

import { PATCH } from '@/app/api/to-haejung/[id]/route';

function makeRequest(body: unknown, id = '1') {
  return new NextRequest(`http://localhost/api/to-haejung/${id}`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

describe('PATCH /api/to-haejung/[id]', () => {
  beforeEach(() => jest.clearAllMocks());

  it('returns 200 on valid field update', async () => {
    const req = makeRequest({ college: '공과대학' });
    const res = await PATCH(req, { params: { id: '1' } });
    expect(res.status).toBe(200);
    const data = await res.json();
    expect(data.ok).toBe(true);
  });

  it('returns 400 for unknown field (whitelist enforcement)', async () => {
    const req = makeRequest({ malicious_field: 'value' });
    const res = await PATCH(req, { params: { id: '1' } });
    expect(res.status).toBe(400);
  });

  it('returns 400 for empty body', async () => {
    const req = makeRequest({});
    const res = await PATCH(req, { params: { id: '1' } });
    expect(res.status).toBe(400);
  });

  it('returns 400 for non-integer id', async () => {
    const req = makeRequest({ college: '공과대학' }, 'abc');
    const res = await PATCH(req, { params: { id: 'abc' } });
    expect(res.status).toBe(400);
  });

  it('returns 404 when id does not exist', async () => {
    mockRun.mockReturnValueOnce({ changes: 0 });
    const req = makeRequest({ college: '공과대학' }, '999');
    const res = await PATCH(req, { params: { id: '999' } });
    expect(res.status).toBe(404);
  });
});
